package ca.yorku.eecs3311.coursepilot.cli; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.RecommendationService; import org.springframework.stereotype.Component; import picocli.CommandLine.*;
@Component @Command(name="recommend",description="Recommend the next supported study action",mixinStandardHelpOptions=true) public class RecommendationCommand implements Runnable{private final RecommendationService recommendations;private final StudyAgentFacade facade;public RecommendationCommand(RecommendationService r,StudyAgentFacade f){recommendations=r;facade=f;}@Option(names="--course",required=true)String course;public void run(){var c=facade.getCourseByCode(course);var r=recommendations.recommend(c.id());System.out.println(r.action()+": "+r.reason());}}
